@Environment(EnvType.CLIENT)
@Mixin({class_897.class})
public class EntityCullingMixin<T extends class_1297> {
  @Inject(method = {"method_3933"}, at = {@At("HEAD")}, cancellable = true)
  private void onShouldRender(T entity, class_4604 frustum, double x, double y, double z, CallbackInfoReturnable<Boolean> cir) {
    if (entity.method_5767())
      cir.setReturnValue(Boolean.valueOf(false)); 
  }

  @Inject(method = {"method_3933"}, at = {@At("HEAD")}, cancellable = true)
  private void hideInvisibleEntities(T entity, class_4604 frustum, double x, double y, double z, CallbackInfoReturnable<Boolean> cir) {
    if (!frustum.method_23093(entity.method_5829()))
      cir.setReturnValue(Boolean.valueOf(false)); 
  }
}
)
